#[derive(Default, PartialEq, Debug, Clone)]
pub struct AccessControlList {
    /// The "extends" allows us to chain together ACLs without needing to copy
    /// the whole thing. For example, if want to grant Alice access to a file,
    /// we would create a new ACL for that file that has Alice in the permissions
    /// list but extends the parent directory's ACL to retain all the existing
    /// permissions. This can also be used to selectively revoke access (by
    /// adding an ACL entry with empty permissions) to an object.
    extends: Option<ObjectId>,
    roles: Vec<Role>,
}

impl AccessControlList {
    pub fn serialize_to<'a>(&self, builder: &mut flatbuffers::FlatBufferBuilder<'a>) -> flatbuffers::WIPOffset<FbsAccessControlList<'a>> {
        use crate::types::generated::permissions_generated::AccessControlListBuilder as FbsAccessControlListBuilder;

        let extends_offset = self.extends.as_ref().map(|o| o.serialize_to(builder));
        let mut roles_offsets = Vec::with_capacity(self.roles.len());
        for val in self.roles.iter() {
            let offset = val.serialize_to(builder);
            roles_offsets.push(offset);
        }
        let roles_offset = builder.create_vector(&roles_offsets);

        let mut bldr = FbsAccessControlListBuilder::new(builder);
        if let Some(offset) = extends_offset {
            bldr.add_extends(offset);
        }
        bldr.add_roles(roles_offset);
        bldr.finish()
    }
}

impl From<FbsAccessControlList<'_>> for AccessControlList {
    fn from(fbs: FbsAccessControlList<'_>) -> Self {
        let extends = fbs.extends().map(ObjectId::from);
        let mut roles = Vec::new();
        for elem in fbs.roles() {
            roles.push(elem.into());
        }

        Self {
            extends,
            roles,
        }
    }
}

impl TryFrom<&[u8]> for AccessControlList {
    type Error = flatbuffers::InvalidFlatbuffer;
    fn try_from(bytes: &[u8]) -> Result<Self, Self::Error> {
        let fbs = flatbuffers::size_prefixed_root::<FbsAccessControlList>(bytes)?;
        Ok(Self::from(fbs))
    }
}

impl From<AccessControlList> for Vec<u8> {
    fn from(obj: AccessControlList) -> Self {
        let mut bldr = flatbuffers::FlatBufferBuilder::new();
        let offset = obj.serialize_to(&mut bldr);
        bldr.finish_size_prefixed(offset, None);
        bldr.finished_data().to_vec()
    }
}

#[derive(Default, PartialEq, Debug, Clone)]
